// Extract Jira ticket fields from webhook payload.
// Also flag whether this is a subtask transition vs a parent ticket update.
const body   = $input.first().json.body || $input.first().json;
const issue  = body.issue || {};
const fields = issue.fields || {};
const issueType = (fields.issuetype && fields.issuetype.name) || '';
const isSubtask = (fields.issuetype && fields.issuetype.subtask) === true;
const parentKey = (fields.parent && fields.parent.key) || '';

return [{
  json: {
    issueKey:    issue.key || '',
    summary:     fields.summary || '',
    description: fields.description || '',
    status:      (fields.status && fields.status.name) || '',
    statusNormalized: ((fields.status && fields.status.name) || '').trim().toLowerCase(),
    assignee:    (fields.assignee && fields.assignee.displayName) || '',
    email:       (fields.assignee && fields.assignee.emailAddress) || '',
    priority:    (fields.priority && fields.priority.name) || '',
    issueType,
    isSubtask,
    parentKey,
    reporter:    (fields.reporter && fields.reporter.displayName) || '',
    projectKey:  (fields.project && fields.project.key) || '',
    repoUrl:     (fields.customfield_repo_url) || ''
  }
}];

// Normalize testcases array into a single comment body + DB rows.
const api = $input.first().json;
const jiraCtx = $('Extract Jira Fields').first().json;

const testcases = api.testcases || api.test_cases || [];
const total = testcases.length;

// Build ONE comment containing all test cases, using Jira wiki markup.
const blocks = testcases.map((tc, i) => {
  const title = tc.title || tc.name || `Test Case ${i + 1}`;
  const steps = (tc.steps || []).map((s, j) => `  ${j + 1}. ${s}`).join('\n');
  const expected = tc.expected || tc.expected_result || '';
  let b = `*[TC ${i + 1}] ${title}*`;
  if (steps)    b += `\n_Steps:_\n${steps}`;
  if (expected) b += `\n_Expected:_ ${expected}`;
  return b;
}).join('\n\n----\n\n');

const commentBody =
  `h3. 🧪 Auto-generated Test Cases (${total})\n` +
  `_Generated by AI Governor RepoTree for ${jiraCtx.issueKey}._\n` +
  `{anchor:AI-GOVERNOR-TESTCASES-V1}\n\n` +
  blocks;

const slackMessage = `🧪 *Test cases generated for ${jiraCtx.issueKey}*\n` +
  `Summary: ${jiraCtx.summary}\n` +
  `Total test cases: *${total}* (posted as a comment on the ticket)\n` +
  `<https://{{YOUR_JIRA_DOMAIN}}/browse/${jiraCtx.issueKey}|Open in Jira>`;

return [{
  json: {
    ...jiraCtx,
    totalTestcases: total,
    testcases,
    commentBody,
    slackMessage
  }
}];

// Flatten testcases into rows for Postgres bulk insert.
// Test cases now live in a ticket comment (no subtasks), so no subtask_key.
const ctx = $input.first().json;
const tcs = ctx.testcases || [];

const rows = tcs.map((tc, i) => ({
  jira_ticket_id: ctx.issueKey,
  tc_index: i + 1,
  subtask_key: null, // no longer creating subtasks; kept for schema compatibility
  title: tc.title || tc.name || `Test Case ${i + 1}`,
  steps: JSON.stringify(tc.steps || []),
  expected: tc.expected || tc.expected_result || ''
}));

return [{
  json: {
    ...ctx,
    rowsToInsert: rows,
    commentPosted: ctx.commentPosted === true,
    totalTestcases: tcs.length
  }
}];

